-- بيانات مقرر فيزياء 3-2 (المقرر 104، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys32-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C2-L2-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا يُصمَّم الفولتمتر بحيث تكون مقاومته كبيرة جدًّا؟', null, null, '["حتى يمر فيه معظم تيار الدائرة فتكون قراءته للجهد دقيقة","لأنه يوصل على التوالي فيجب أن يحدّ من تيار الدائرة","حتى يكون التغير في تيارات الدائرة وفروق جهدها أقل ما يمكن","حتى يرفع فرق الجهد بين طرفي الجزء الذي يقيس جهده"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر)'),
('mcq', 2, 'في الدائرة الآتية مقاومة الفولتمتر 20.0 kΩ. ما مقدار المقاومة المكافئة للمقاومة $\mathrm{R}_\mathrm{B}$ والفولتمتر معًا؟', null, '[{"src":"qimg/phys32/c2l2-o07-vm.svg","alt":"دائرة: بطارية جهدها 12.0 V على اليسار قطبها الموجب أعلى، والسلك العلوي يصل إلى مقاومتين رأسيتين على التوالي على اليمين: R_A وقيمتها 20.0 Ω (أعلى) ثم R_B وقيمتها 20.0 Ω (أسفل)، ثم يعود السلك السفلي إلى البطارية. فولتمتر (V) موصول بسلكين بطرفي R_B (من النقطة بين المقاومتين إلى أسفل R_B)."}]'::jsonb, '["19.98 Ω","20 020 Ω","10.0 Ω","40.0 Ω"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر) والشكل 2-12b'),
('mcq', 3, 'في الدائرة الآتية استُعمل فولتمتر رديء مقاومته 20.0 Ω فقط. ما قراءته؟', null, '[{"src":"qimg/phys32/c2l2-o07-vm.svg","alt":"دائرة: بطارية جهدها 12.0 V على اليسار قطبها الموجب أعلى، والسلك العلوي يصل إلى مقاومتين رأسيتين على التوالي على اليمين: R_A وقيمتها 20.0 Ω (أعلى) ثم R_B وقيمتها 20.0 Ω (أسفل)، ثم يعود السلك السفلي إلى البطارية. فولتمتر (V) موصول بسلكين بطرفي R_B (من النقطة بين المقاومتين إلى أسفل R_B)."}]'::jsonb, '["6.00 V","8.00 V","12.0 V","4.00 V"]'::jsonb, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر) والشكل 2-12b'),
('mcq', 4, 'كيف تُجعل مقاومة الفولتمتر كبيرة جدًّا في تركيبه؟', null, null, '["يوصل مع ملفه مقاومة صغيرة على التوازي","يوصل مع ملفه مقاومة كبيرة على التوالي","يوصل مع ملفه مقاومة صغيرة على التوالي","يوصل مع ملفه مقاومة كبيرة على التوازي"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر)'),
('mcq', 5, 'ماذا يحدث عند توصيل فولتمتر مقاومته كبيرة جدًّا بين طرفي مقاومة في دائرة كهربائية؟', null, null, '["يقل فرق الجهد بين طرفي المقاومة إلى النصف تقريبًا؛ لأن الفولتمتر يتقاسم الجهد معها","ينقطع التيار عن المقاومة؛ لأن التيار كله يمر في الفولتمتر","لا يكاد يتغير تيار الدائرة ولا جهد المقاومة؛ لأنه لا يمر فيه إلا تيار صغير جدًّا","يزداد تيار الدائرة الكلي زيادة كبيرة؛ لأن مقاومة الدائرة الكلية تقل كثيرًا"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر)'),
('mcq', 6, 'عند توصيل فولتمتر مقاومته كبيرة جدًّا على التوازي مع مقاومة صغيرة، فإن المقاومة المكافئة لهما:', null, null, '["تساوي تقريبًا المقاومة الصغيرة","تساوي تقريبًا مقاومة الفولتمتر","تساوي مجموع المقاومتين","تساوي نصف المقاومة الصغيرة"]'::jsonb, 'فهم', 'استدلال', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر) والشكل 2-12b'),
('mcq', 7, 'أردت قياس الهبوط في الجهد عبر مقاومة 2.0 kΩ في دائرة. أيّ الفولتمترات الآتية تختار؟', null, null, '["فولتمتر مقاومته 0.01 Ω","فولتمتر مقاومته 10 Ω","فولتمتر مقاومته 1 kΩ","فولتمتر مقاومته 1000 kΩ"]'::jsonb, 'تقويم', 'اختيار جهاز', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر)'),
('essay', 1, 'لماذا يُصمَّم الفولتمتر بحيث تكون مقاومته كبيرة جدًّا؟ وكيف تُجعل مقاومته كبيرة في تركيبه؟', null, null, null, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر)، والتقويم ص 62 السؤال 38'),
('essay', 2, 'في الدائرة الآتية يوصل فولتمتر بطرفي $\mathrm{R}_\mathrm{B}$. (a) احسب الهبوط في الجهد عبر $\mathrm{R}_\mathrm{B}$ دون فولتمتر. (b) احسب قراءة فولتمتر مقاومته 1000 kΩ. (c) احسب قراءة فولتمتر مقاومته 1.0 kΩ. (d) قارن النتيجتين، وفسّر بهما سبب تصميم الفولتمتر بمقاومة كبيرة جدًّا.', null, '[{"src":"qimg/phys32/c2l2-o07-e2.svg","alt":"دائرة: بطارية جهدها 9.0 V على اليسار قطبها الموجب أعلى، والسلك العلوي يصل إلى مقاومتين رأسيتين على التوالي على اليمين: R_A وقيمتها 1.0 kΩ (أعلى) ثم R_B وقيمتها 1.0 kΩ (أسفل)، ثم يعود السلك السفلي إلى البطارية. فولتمتر (V) موصول بطرفي R_B."}]'::jsonb, null, 'تطبيق', 'مسألة حسابية', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر) والشكل 2-12b'),
('essay', 3, 'قال طالب: «كلما كبرت مقاومة الفولتمتر قلّ التيار المار فيه، فيصعب عليه قياس الجهد بدقة؛ لذا يجب أن تكون مقاومته صغيرة». قيّم قول الطالب، مبيّنًا ما يحدث لدائرة توالٍ فيها مقاومتان متساويتان عند وصل فولتمتر بين طرفي إحداهما في حالتين: مقاومة الفولتمتر كبيرة جدًّا، ومقاومته صغيرة جدًّا.', null, null, null, 'تقويم', 'تقييم ادعاء', 'صعب', 'الكتاب ص 57 — الأميترات والفولتمترات (مقاومة الفولتمتر)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يوصل الفولتمتر على التوازي بين طرفي الجزء المراد قياس الهبوط في الجهد عبره، ويُصمَّم بحيث تكون مقاومته كبيرة جدًّا؛ وذلك حتى يكون التغير في التيارات وفروق الجهد في الدائرة الكهربائية أقل ما يمكن.', '["المقاومة الكبيرة تجعل التيار المار في الفولتمتر صغيرًا جدًّا لا كبيرًا.","الفولتمتر يوصل على التوازي لا على التوالي.","","الفولتمتر المثالي لا يغيّر فرق الجهد الذي يقيسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (73%)"}],"at":"2026-11-27T21:51:39.412Z"}'::jsonb),
('mcq', 2, 0, 'الفولتمتر على التوازي مع $\mathrm{R}_\mathrm{B}$: $\frac{1}{\mathrm{R}} = \frac{1}{20.0\ \Omega} + \frac{1}{20000\ \Omega}$ فـ $\mathrm{R} = 19.98\ \Omega$؛ أي إن المقاومة الكبيرة جدًّا للفولتمتر لا تكاد تغيّر مقاومة هذا الجزء، فلا يتغير التيار ولا فرق الجهد تقريبًا.', '["","جمع المقاومتين كأنهما على التوالي، مع أن الفولتمتر موصول على التوازي.","عامل مقاومة الفولتمتر كأنها 20.0 Ω (نسي تحويل kΩ).","جمع $\\mathrm{R}_\\mathrm{A}$ و$\\mathrm{R}_\\mathrm{B}$ وأهمل الفولتمتر، وهذه ليست المقاومة المطلوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.412Z"}'::jsonb),
('mcq', 3, 3, 'الفولتمتر على التوازي مع $\mathrm{R}_\mathrm{B}$ فمقاومتهما المكافئة $10.0\ \Omega$، والمقاومة الكلية $20.0 + 10.0 = 30.0\ \Omega$، والتيار $\mathrm{I} = \frac{12.0}{30.0} = 0.400\ \text{A}$، فقراءة الفولتمتر $\mathrm{V} = (0.400\ \text{A})(10.0\ \Omega) = 4.00\ \text{V}$ بدل 6.00 V؛ فالفولتمتر ذو المقاومة الصغيرة غيّر الجهد الذي يقيسه.', '["هذه قيمة الهبوط في الجهد عبر $\\mathrm{R}_\\mathrm{B}$ دون فولتمتر؛ أهمل أثر مقاومته الصغيرة.","هذا الهبوط في الجهد عبر $\\mathrm{R}_\\mathrm{A}$ بعد توصيل الفولتمتر لا عبر $\\mathrm{R}_\\mathrm{B}$.","هذا جهد البطارية كله.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.412Z"}'::jsonb),
('mcq', 4, 1, 'يوصل مع ملف الفولتمتر مقاومة كبيرة على التوالي، فتصبح مقاومته الكلية كبيرة جدًّا.', '["هذا تركيب الأميتر، وهو يجعل المقاومة صغيرة جدًّا.","","المقاومة الصغيرة على التوالي لا تجعل المقاومة الكلية كبيرة جدًّا.","المقاومة على التوازي تُنقص المقاومة المكافئة ولا تزيدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-27T21:51:39.413Z"}'::jsonb),
('mcq', 5, 2, 'المقاومة الكبيرة جدًّا للفولتمتر الموصول على التوازي تجعل التيار المار فيه صغيرًا جدًّا، وتبقى المقاومة المكافئة للجزء تقريبًا كما هي؛ فيكون التغير في تيار الدائرة وجهدها مهملًا.', '["هذا يحدث لو كانت مقاومة الفولتمتر مساوية لمقاومة الجزء، لا كبيرة جدًّا.","المقاومة الكبيرة جدًّا يمر فيها تيار صغير جدًّا لا التيار كله.","","المقاومة المكافئة لا تكاد تتغير عند وصل مقاومة كبيرة جدًّا على التوازي، فلا يتغير التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-27T21:51:39.413Z"}'::jsonb),
('mcq', 6, 0, 'مقلوب المقاومة المكافئة يساوي مجموع مقلوب المقاومة الصغيرة ومقلوب مقاومة الفولتمتر، والحد الثاني صغير جدًّا لأن مقاومة الفولتمتر كبيرة جدًّا؛ فتكون المقاومة المكافئة أصغر بقليل جدًّا من المقاومة الصغيرة، أي تساويها تقريبًا.', '["","المقاومة المكافئة لمقاومتين على التوازي أصغر من أصغرهما.","المجموع يكون في التوصيل على التوالي.","النصف يكون عندما تتساوى المقاومتان، لا عندما تكون إحداهما كبيرة جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-27T21:51:39.413Z"}'::jsonb),
('mcq', 7, 3, 'الفولتمتر الذي مقاومته 1000 kΩ أكبر كثيرًا من 2.0 kΩ؛ فعند وصله على التوازي تبقى المقاومة المكافئة تقريبًا 2.0 kΩ ($\approx 1.996\ \text{k}\Omega$)، فيكون التغير في تيارات الدائرة وفروق جهدها أقل ما يمكن وتكون قراءته أقرب إلى القيمة الحقيقية.', '["مقاومة صغيرة جدًّا على التوازي تكوّن ما يشبه دائرة قصر حول المقاومة، وتناسب الأميتر لا الفولتمتر.","مقاومة صغيرة على التوازي تُنقص مقاومة الجزء كثيرًا فتغيّر الجهد المقيس.","مقاومة أصغر من 2.0 kΩ تُنقص المقاومة المكافئة إلى نحو الثلث فتتغير القراءة كثيرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.413Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُستخدم الفولتمتر لقياس الهبوط في الجهد عبر جزء من الدائرة، ويوصل على التوازي مع هذا الجزء؛ فيكوّن فرعًا جديدًا يمكن أن يسحب جزءًا من التيار ويغيّر المقاومة المكافئة. لذلك يُصمَّم بحيث تكون مقاومته كبيرة جدًّا؛ حتى يكون التيار المار فيه صغيرًا جدًّا، ويكون التغير في التيارات وفروق الجهد في الدائرة أقل ما يمكن. ولتحقيق ذلك يوصل مع ملفه مقاومة كبيرة على التوالي.', '["يوصل على التوازي فيكوّن فرعًا جديدًا","مقاومته الكبيرة تجعل تياره صغيرًا جدًّا والتغير في الدائرة أقل ما يمكن","مقاومة كبيرة على التوالي مع ملفه"]'::jsonb, '[]'::jsonb, '[{"element":"التوصيل على التوازي","marks":1},{"element":"التعليل","marks":1},{"element":"طريقة التركيب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعليل وطريقة التركيب صحيحان"},{"level":"2 درجتان","description":"التعليل صحيح دون طريقة التركيب"},{"level":"1 درجة","description":"ذكر التوصيل على التوازي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن مقاومته كبيرة كي يمر فيه تيار كبير","القول إن المقاومة الكبيرة توصل على التوازي مع ملفه","الخلط مع تعليل مقاومة الأميتر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (73%)"}],"at":"2026-11-27T21:51:39.413Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) المقاومتان متساويتان فيقسم الجهد بينهما: $\mathrm{V}_\mathrm{B} = \frac{9.0}{2} = 4.5\ \text{V}$. (b) المكافئة لـ $\mathrm{R}_\mathrm{B}$ والفولتمتر $\frac{1}{\mathrm{R}} = \frac{1}{1.0} + \frac{1}{1000}$ فـ $\mathrm{R} = 0.999\ \text{k}\Omega$، والقراءة $\mathrm{V} = 9.0 \times \frac{0.999}{1.0 + 0.999} = 4.5\ \text{V}$ تقريبًا (4.498 V). (c) المكافئة $0.50\ \text{k}\Omega$، والقراءة $\mathrm{V} = 9.0 \times \frac{0.50}{1.50} = 3.0\ \text{V}$. (d) الفولتمتر ذو المقاومة الكبيرة جدًّا لم يغيّر الجهد تقريبًا (4.5 V)، أما ذو المقاومة 1.0 kΩ فخفّض الجهد المقيس إلى 3.0 V لأنه سحب تيارًا كبيرًا وأنقص مقاومة الجزء إلى النصف؛ لذا يُصمَّم الفولتمتر بمقاومة كبيرة جدًّا حتى يكون التغير في التيارات وفروق الجهد أقل ما يمكن.', '["4.5 V دون فولتمتر","4.5 V تقريبًا بالفولتمتر 1000 kΩ","3.0 V بالفولتمتر 1.0 kΩ","المقارنة والتفسير"]'::jsonb, '["$\\mathrm{V}_\\mathrm{B} = \\mathrm{V}\\frac{\\mathrm{R}_\\mathrm{B}}{\\mathrm{R}_\\mathrm{A} + \\mathrm{R}_\\mathrm{B}} = 4.5\\ \\text{V}$","المقاومة المكافئة لـ $\\mathrm{R}_\\mathrm{B}$ والفولتمتر $0.999\\ \\text{k}\\Omega$ ← $\\mathrm{V} \\approx 4.5\\ \\text{V}$","المقاومة المكافئة لـ $\\mathrm{R}_\\mathrm{B}$ والفولتمتر $0.50\\ \\text{k}\\Omega$ ← $\\mathrm{V} = 3.0\\ \\text{V}$"]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والتفسير صحيحة"},{"level":"2–3 درجات","description":"حسابان صحيحان مع تفسير ناقص"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع مقاومة الفولتمتر مع $\\mathrm{R}_\\mathrm{B}$ على التوالي","إهمال أثر الفولتمتر 1.0 kΩ","القول إن الفولتمتر الأصغر مقاومة أدق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.413Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. الفولتمتر يوصل على التوازي، والمطلوب ألّا يغيّر التيارات وفروق الجهد التي يقيسها. إذا كانت مقاومته كبيرة جدًّا مر فيه تيار صغير جدًّا وبقيت المقاومة المكافئة للجزء تقريبًا كما هي، فيبقى الهبوط في الجهد عبر المقاومة نصف جهد المصدر تقريبًا، وتكون القراءة قريبة من القيمة الحقيقية. أما إذا كانت مقاومته صغيرة جدًّا فإنه يسحب معظم التيار وتصبح المقاومة المكافئة لذلك الجزء صغيرة جدًّا، فيقل الهبوط في الجهد عبره كثيرًا ويكاد يقرأ صفرًا، ويتغير تيار الدائرة كله. لذا يُصمَّم الفولتمتر بمقاومة كبيرة جدًّا حتى يكون التغير في التيارات وفروق الجهد أقل ما يمكن.', '["الحكم: القول غير صحيح","المطلوب ألّا يغيّر الفولتمتر الدائرة","المقاومة الكبيرة: القراءة قريبة من الحقيقية","المقاومة الصغيرة: يقل الجهد المقيس كثيرًا ويتغير التيار","الاستنتاج"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المبدأ","marks":1},{"element":"حالة المقاومة الكبيرة","marks":1},{"element":"حالة المقاومة الصغيرة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح مع تحليل الحالتين والاستنتاج"},{"level":"3–4 درجات","description":"حكم صحيح مع تحليل حالة واحدة"},{"level":"1–2 درجة","description":"حكم صحيح دون تحليل كافٍ"},{"level":"صفر","description":"تأييد قول الطالب أو لا إجابة"}]'::jsonb, '["القول إن الفولتمتر يحتاج إلى تيار كبير ليقيس","القول إن مقاومة الفولتمتر لا تؤثر في الدائرة مهما كانت","وصل الفولتمتر على التوالي في التحليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-27T21:51:39.414Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
