('mcq', 1, 0, 'تيار كل جهاز $\mathrm{I} = \frac{\mathrm{P}}{\mathrm{V}}$: التلفاز $\frac{120}{120} = 1.0\ \text{A}$، والمكواة $\frac{960}{120} = 8.0\ \text{A}$، والغلاية $\frac{1200}{120} = 10\ \text{A}$. المنصهر على التوالي بالمصدر فيمر فيه مجموعها $19\ \text{A}$، وهو أكبر من قدرة تحمله 15 A؛ فينصهر ويفتح الدائرة.', '["","الحساب صحيح لكن الحكم خاطئ؛ التيار الكلي المار في المنصهر 19 A أكبر من 15 A فينصهر.","هذا تيار الغلاية وحدها، والمنصهر يمر فيه مجموع التيارات.","قسم متوسط القدرات (760 W) على الجهد بدل جمع التيارات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-27T21:51:39.415Z"}'::jsonb),
('mcq', 2, 3, '$\mathrm{I} = \frac{\mathrm{P}}{\mathrm{V}} = \frac{1080\ \text{W}}{120\ \text{V}} = 9.0\ \text{A}$.', '["قلب العلاقة فقسم الجهد على القدرة.","هذه مقاومة المجفف بالأوم ($\\frac{\\mathrm{V}^2}{\\mathrm{P}} = 13\\ \\Omega$) لا تياره.","ضرب القدرة في الجهد بدل القسمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-27T21:51:39.415Z"}'::jsonb),
('mcq', 3, 1, 'المقاومة المكافئة: $\frac{1}{\mathrm{R}} = \frac{1}{40} + \frac{1}{24} + \frac{1}{30} = \frac{1}{10}$ فـ $\mathrm{R} = 10\ \Omega$، والتيار الكلي $\mathrm{I} = \frac{120\ \text{V}}{10\ \Omega} = 12\ \text{A}$ (ويساوي مجموع $3.0 + 5.0 + 4.0$). وهو أقل من 15 A فلا ينصهر المنصهر.', '["جمع المقاومات كأنها على التوالي (94 Ω).","","الحساب صحيح لكن 12 A أقل من قدرة تحمل المنصهر 15 A فلا ينصهر.","هذا تيار الجهاز الذي مقاومته 24 Ω وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-27T21:51:39.415Z"}'::jsonb),
('mcq', 4, 2, 'حدثت دائرة قصر: $\mathrm{I} = \frac{\mathrm{V}}{\mathrm{R}} = \frac{120\ \text{V}}{0.020\ \Omega} = 6.0 \times 10^3\ \text{A}$، وهو أكبر كثيرًا من 15 A فينصهر المنصهر ويفتح الدائرة قبل أن تسخن الأسلاك إلى حد الحريق.', '["ضرب الجهد في المقاومة بدل القسمة.","قسم المقاومة على الجهد.","","أخطأ في الفاصلة العشرية فاستعمل 0.20 Ω."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-27T21:51:39.415Z"}'::jsonb),
('mcq', 5, 1, 'تيار السخّان $\frac{1080}{120} = 9.0\ \text{A}$، فيبقى للمصابيح $15 - 9.0 = 6.0\ \text{A}$. تيار كل مصباح $\frac{100}{120} = 0.833\ \text{A}$، و$\frac{6.0}{0.833} = 7.2$؛ فأكبر عدد 7 مصابيح (التيار الكلي 14.8 A)، أما 8 مصابيح فتجعله 15.7 A فينصهر المنصهر.', '["قرّب 7.2 إلى الأعلى، و8 مصابيح تجعل التيار الكلي 15.7 A أكبر من 15 A.","","أهمل تيار السخّان وقسم 15 A على تيار المصباح.","طرح تيار السخّان (9.0 A) من عدد المصابيح (18) كأنهما من النوع نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-27T21:51:39.416Z"}'::jsonb),
('mcq', 6, 0, 'تيار كل مصباح $\frac{120}{240} = 0.500\ \text{A}$، فتيار المصابيح الستة $3.00\ \text{A}$، وتيار المدفأة $\frac{120}{12.0} = 10.0\ \text{A}$، والتيار الكلي $13.0\ \text{A}$ أكبر من 12 A؛ فينصهر المنصهر.', '["","حسب تيار مصباح واحد فقط مع المدفأة.","عامل المصابيح الستة كأنها على التوالي (1440 Ω) فأخذ لها نحو 0.08 A.","أهمل تيار المدفأة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-27T21:51:39.416Z"}'::jsonb),
('mcq', 7, 3, 'تيارات الأجهزة $\mathrm{I} = \frac{\mathrm{P}}{\mathrm{V}}$: المكيّف 12 A، والمكواة 7.0 A، والغسالة 5.0 A، والتلفاز 1.0 A. المكيّف والغسالة معًا $12 + 5.0 = 17\ \text{A}$ أكبر من 15 A فينصهر المنصهر.', '["مجموع تياراتها $7.0 + 5.0 + 1.0 = 13\\ \\text{A}$ أقل من 15 A.","مجموع تياريهما $12 + 1.0 = 13\\ \\text{A}$ أقل من 15 A.","مجموع تياريهما $7.0 + 5.0 = 12\\ \\text{A}$ أقل من 15 A.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-27T21:51:39.416Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $\mathrm{I} = \frac{\mathrm{P}}{\mathrm{V}}$: التلفاز $\frac{180}{120} = 1.5\ \text{A}$، والمكواة $\frac{1080}{120} = 9.0\ \text{A}$، والمجفف $\frac{840}{120} = 7.0\ \text{A}$. (b) $\mathrm{R} = \frac{\mathrm{V}}{\mathrm{I}}$: التلفاز $80\ \Omega$، والمكواة $13\ \Omega$ (13.3 Ω)، والمجفف $17\ \Omega$ (17.1 Ω). (c) $\frac{1}{\mathrm{R}} = \frac{1}{80} + \frac{1}{13.3} + \frac{1}{17.1}$ فـ $\mathrm{R} = 6.9\ \Omega$. (d) بالجمع: $1.5 + 9.0 + 7.0 = 17.5\ \text{A}$، وبالمقاومة المكافئة: $\mathrm{I} = \frac{120\ \text{V}}{6.86\ \Omega} = 17.5\ \text{A}$. الحكم: 17.5 A أكبر من قدرة تحمل المنصهر 15 A فينصهر ويفتح الدائرة.', '["تيارات الأجهزة 1.5 A و9.0 A و7.0 A","المقاومات 80 Ω و13 Ω و17 Ω","$\\mathrm{R} = 6.9\\ \\Omega$","التيار الكلي 17.5 A بطريقتين","الحكم: ينصهر"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{P}}{\\mathrm{V}}$ لكل جهاز","$\\mathrm{R} = \\frac{\\mathrm{V}}{\\mathrm{I}}$ لكل جهاز","$\\frac{1}{\\mathrm{R}} = \\frac{1}{80\\ \\Omega} + \\frac{1}{13.3\\ \\Omega} + \\frac{1}{17.1\\ \\Omega}$ ← $\\mathrm{R} = 6.9\\ \\Omega$","$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}} = 17.5\\ \\text{A}$","المقارنة بـ 15 A"]'::jsonb, '[{"element":"التيارات","marks":1},{"element":"المقاومات","marks":1},{"element":"المقاومة المكافئة","marks":1},{"element":"التيار الكلي بطريقتين","marks":1},{"element":"الحكم","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات والحكم صحيحة"},{"level":"3–4 درجات","description":"التيار الكلي والحكم صحيحان مع خطأ في المقاومات"},{"level":"1–2 درجة","description":"تيارات الأجهزة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع المقاومات على التوالي","مقارنة تيار جهاز واحد بقدرة تحمل المنصهر","حساب $\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{P}}$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-27T21:51:39.416Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{I} = \frac{\mathrm{P}}{\mathrm{V}} = \frac{100\ \text{W}}{120\ \text{V}} = 0.83\ \text{A}$. (b) دائرة قصر: $\mathrm{I} = \frac{120\ \text{V}}{0.015\ \Omega} = 8.0 \times 10^3\ \text{A}$. (c) تيار دائرة القصر أكبر من تيار التشغيل الطبيعي بنحو عشرة آلاف مرة، وأكبر كثيرًا من 15 A؛ فينصهر المنصهر ويفتح الدائرة. ولو لم يوجد منصهر أو قاطع لأنتج هذا التيار الكبير طاقة حرارية كبيرة ترفع درجة حرارة الأسلاك إلى حد إشعال الحريق.', '["0.83 A","$8.0 \\times 10^3\\ \\text{A}$","المقارنة والحكم: ينصهر","خطر الحريق دون منصهر"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{P}}{\\mathrm{V}} = 0.83\\ \\text{A}$","$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}} = \\frac{120}{0.015} = 8.0 \\times 10^3\\ \\text{A}$","$8.0 \\times 10^3\\ \\text{A} > 15\\ \\text{A}$"]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"الحكم","marks":1},{"element":"النتيجة دون منصهر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان والحكم والنتيجة صحيحة"},{"level":"2–3 درجات","description":"الحسابان صحيحان مع نقص في التفسير"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الجهد في المقاومة في (b)","القول إن التيار يقل عند تلامس السلكين","إغفال أثر الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-27T21:51:39.417Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التيارات: الغلاية $\frac{1800}{120} = 15\ \text{A}$، والفرن $\frac{1200}{120} = 10\ \text{A}$، والمصباح $\frac{120}{120} = 1.0\ \text{A}$. (a) الغلاية والفرن: $15 + 10 = 25\ \text{A}$ أكبر من 20 A، فينصهر المنصهر؛ لا يمكن تشغيلهما معًا. (b) الغلاية والمصباح: $15 + 1.0 = 16\ \text{A}$ أقل من 20 A، فيمكن تشغيلهما معًا. (c) الاقتراح خطِر وغير مقبول؛ لأن أسلاك الدائرة صُممت لتيار لا يتجاوز 20 A، فإذا استُعمل منصهر 30 A أمكن أن يمر فيها 25 A دون أن ينصهر، فتسخن الأسلاك وقد تنصهر مادتها العازلة وتحدث دائرة قصر أو حريق. والحل أن يُشغّل الجهازان في وقتين مختلفين، أو أن يُوصل أحدهما بدائرة أخرى لها منصهرها.', '["التيارات 15 A و10 A و1.0 A","(a) 25 A > 20 A: لا يمكن","(b) 16 A < 20 A: يمكن","(c) الاقتراح خطِر مع التعليل","حل بديل آمن"]'::jsonb, '["$\\mathrm{I} = \\frac{\\mathrm{P}}{\\mathrm{V}}$ لكل جهاز","$15 + 10 = 25\\ \\text{A} > 20\\ \\text{A}$","$15 + 1.0 = 16\\ \\text{A} < 20\\ \\text{A}$"]'::jsonb, '[{"element":"التيارات","marks":1},{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"تقييم الاقتراح","marks":1},{"element":"الحل البديل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات والأحكام والتقييم صحيحة"},{"level":"3–4 درجات","description":"الحكمان صحيحان مع تقييم ناقص"},{"level":"1–2 درجة","description":"حساب التيارات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تأييد استبدال المنصهر بآخر أكبر","مقارنة تيار كل جهاز وحده بقدرة تحمل المنصهر","جمع القدرات ومقارنتها بالتيار مباشرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-27T21:51:39.417Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
