select (select id from public.objectives where code = 'P32-C2-L2-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في الدائرة المنزلية الآتية يضعف ضوء المصباح عند إغلاق المفتاح S لتشغيل مجفف الشعر. ما سبب ذلك؟', null, '[{"src":"qimg/phys32/c2l2-o09-house.svg","alt":"دائرة منزلية: طرفا مصدر جهد 120 V على اليسار، وفي السلك العلوي منصهر ثم مقاومة صغيرة مكتوب تحتها «مقاومة أسلاك التمديدات»، ثم نقطة تفرّع يخرج منها فرعان على التوازي بين السلك العلوي والسلك السفلي: فرع فيه مصباح، وفرع فيه مفتاح S مفتوح ثم مقاومة تمثل مجفف شعر."}]'::jsonb, '["يقل التيار الكلي في الدائرة؛ لأن المجفف يزيد المقاومة المكافئة لها","يزداد التيار الكلي فيزداد الهبوط في الجهد عبر الأسلاك، فيقل جهد المصباح","ينقسم تيار المصدر الثابت بين المصباح والمجفف، فيقل نصيب المصباح منه","ينخفض جهد المصدر نفسه من 120 V إلى قيمة أقل عند تشغيل المجفف"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح) والشكل 2-11'),
('mcq', 2, 'المصباح ومجفف الشعر في المنزل موصولان على التوازي. لماذا لا يُتوقع أن يتغير تيار المصباح عند تشغيل المجفف لو كانت مقاومة أسلاك التمديدات صفرًا؟', null, null, '["لأن جهد المصباح يبقى مساويًا لجهد المصدر مهما شُغّل من أجهزة على التوازي","لأن التيار الكلي للدائرة لا يتغير بتشغيل أجهزة إضافية على التوازي","لأن مقاومة المجفف كبيرة جدًّا فلا يمر فيه تيار يُذكر عند تشغيله","لأن المجفف يوصل على التوالي مع المصباح فيمر فيهما التيار نفسه"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح)'),
('mcq', 3, 'كيف تتصل مقاومة أسلاك التمديدات المنزلية بالأجهزة الكهربائية في المنزل؟', null, null, '["على التوازي مع كل جهاز، فتكوّن معها دائرة توازٍ لا توالي فيها","على التوالي مع كل جهاز على حدة، فتكوّن مع كل منها دائرة توالٍ بسيطة","على التوالي مع مجموعة الأجهزة المتوازية، فتكوّن معها دائرة مركّبة","لا تتصل بها؛ لأن مقاومة أسلاك التمديدات تساوي صفرًا"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح) والشكل 2-11'),
('mcq', 4, 'في الدائرة المنزلية الآتية، ما فرق الجهد بين طرفي المصباح بعد إغلاق المفتاح S؟', null, '[{"src":"qimg/phys32/c2l2-o09-calc.svg","alt":"دائرة منزلية: طرفا مصدر جهد 120 V على اليسار، وفي السلك العلوي مقاومة الأسلاك وقيمتها 0.60 Ω، ثم نقطة تفرّع يخرج منها فرعان على التوازي: فرع فيه مصباح مقاومته 144 Ω، وفرع فيه مفتاح S مفتوح ثم مجفف شعر مقاومته 16.0 Ω."}]'::jsonb, '["120 V","108 V","4.8 V","115 V"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح)، ومثال 4 ص 55–56'),
('mcq', 5, 'أيّ التعديلات الآتية يقلل ضعف إضاءة المصابيح المنزلية عند تشغيل جهاز يحتاج إلى تيار كبير؟', null, null, '["استعمال أسلاك تمديدات أسمك من النوع نفسه مقاومتها أصغر","استعمال أسلاك تمديدات أطول من النوع نفسه والسمك نفسه","استعمال جهاز قدرته أكبر يحتاج إلى تيار أكبر من الأسلاك","توصيل المصابيح على التوالي مع ذلك الجهاز"]'::jsonb, 'تحليل', 'اقتراح حل', 'صعب', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح)'),
('mcq', 6, 'أيّ الأجهزة الآتية يُتوقع أن يسبّب تشغيله أكبر ضعف في إضاءة مصابيح المنزل؟', null, null, '["شاحن هاتف قدرته 10 W","مصباح صغير قدرته 15 W","مكيّف هواء قدرته 1440 W","ساعة حائط قدرتها 5 W"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'سهل', 'الكتاب ص 59 — الفيزياء في الحياة 2'),
('mcq', 7, 'مقاومة سلكي التمديد بين علبة التوزيع وأجهزة غرفة معًا 0.40 Ω، وجهد المصدر 120 V. إذا مر فيهما تيار كلي مقداره 15 A، فما الجهد الواصل إلى الأجهزة؟', null, null, '["6.0 V","120 V","126 V","114 V"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح)، والتقويم ص 66 السؤال 75'),
('essay', 1, 'لماذا يخفت الضوء في المنزل عند تشغيل جهاز كهربائي يحتاج إلى تيار كبير، كالمكيّف مثلًا، مع أن المصابيح والمكيّف موصولة على التوازي؟ وضّح إجابتك مبيّنًا نوع الدائرة المنزلية.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 59 — الفيزياء في الحياة 2، وص 54'),
('essay', 2, 'في الدائرة المنزلية الآتية، احسب: (a) التيار الكلي وفرق الجهد بين طرفي المصباح والقدرة المستنفدة فيه والمفتاح S مفتوح. (b) القيم نفسها بعد إغلاق المفتاح S. (c) فسّر بالنتائج ضعف إضاءة المصباح.', null, '[{"src":"qimg/phys32/c2l2-o09-calc.svg","alt":"دائرة منزلية: طرفا مصدر جهد 120 V على اليسار، وفي السلك العلوي مقاومة الأسلاك وقيمتها 0.60 Ω، ثم نقطة تفرّع يخرج منها فرعان على التوازي: فرع فيه مصباح مقاومته 144 Ω، وفرع فيه مفتاح S مفتوح ثم مجفف شعر مقاومته 16.0 Ω."}]'::jsonb, null, 'تطبيق', 'مسألة حسابية', 'صعب', 'الكتاب ص 54 — الدوائر الكهربائية المركّبة (ضعف إضاءة المصباح)، ومثال 4 ص 55–56'),
('essay', 3, 'في الدائرة المنزلية الآتية مقاومة كل من سلكي التوصيل 0.30 Ω. والمفتاح S مفتوح: (a) احسب المقاومة المكافئة للدائرة المكوّنة من المصباح وسلكي التوصيل. (b) أوجد التيار المار في المصباح. (c) أوجد القدرة المستنفدة في المصباح. (d) عند إغلاق S وتشغيل المدفأة، تنبأ بما يحدث لسطوع المصباح دون حساب، وعلّل.', null, '[{"src":"qimg/phys32/c2l2-o09-e3.svg","alt":"دائرة منزلية: طرفا مصدر جهد 120 V على اليسار، وفي كل من السلك العلوي والسلك السفلي مقاومة 0.30 Ω تمثل سلك التوصيل، ثم فرعان على التوازي بين السلكين: فرع فيه مصباح مقاومته 200 Ω، وفرع فيه مفتاح S مفتوح ثم مدفأة مقاومتها 12.0 Ω."}]'::jsonb, null, 'تحليل', 'مسألة وتنبؤ', 'صعب', 'الكتاب ص 66 — السؤال 75 والشكل 2-20')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C2-L2-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'مقاومة أسلاك التمديدات صغيرة لكنها موصولة على التوالي مع دائرة التوازي؛ فعند تشغيل المجفف تقل المقاومة المكافئة لجزء التوازي ويزداد التيار الكلي المار في مقاومة الأسلاك، فيزداد الهبوط في الجهد عبرها ويقل فرق الجهد الواصل إلى المصباح فيقل تياره ويضعف ضوؤه.', '["إضافة فرع على التوازي تُنقص المقاومة المكافئة وتزيد التيار الكلي.","","تيار المصدر ليس ثابتًا؛ يزداد التيار الكلي عند تشغيل المجفف، والمشكلة في الهبوط عبر مقاومة الأسلاك.","جهد المصدر ثابت؛ ما يقل هو الجهد الواصل إلى الأجهزة بسبب مقاومة الأسلاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-27T21:51:39.418Z"}'::jsonb),
('mcq', 2, 0, 'في دائرة التوازي تكون الأجهزة موصولة مباشرة بين طرفي المصدر، فيبقى فرق الجهد بين طرفي المصباح مساويًا لجهد المصدر ولا يعتمد تياره على الأجهزة الأخرى؛ أما ضعف الإضاءة فسببه مقاومة الأسلاك الموصولة على التوالي.', '["","التيار الكلي يزداد بتشغيل أجهزة إضافية على التوازي، لكن تيار المصباح لا يتغير.","المجفف يحتاج إلى تيار كبير فمقاومته صغيرة نسبيًّا.","المجفف والمصباح موصولان على التوازي لا على التوالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.418Z"}'::jsonb),
('mcq', 3, 2, 'تتصل المقاومة الصغيرة لأسلاك التمديدات على التوالي مع الأجهزة الموصولة على التوازي، فتكوّن الدائرة المنزلية دائرة مركّبة تحتوي على نوعي التوصيل معًا.', '["مقاومة الأسلاك في المسار الرئيس يمر فيها التيار الكلي، فهي على التوالي لا على التوازي.","الأجهزة نفسها موصولة على التوازي، والمقاومة على التوالي مع مجموعتها كلها.","","لأسلاك التمديدات مقاومة صغيرة لا تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-27T21:51:39.418Z"}'::jsonb),
('mcq', 4, 3, 'بعد الإغلاق: المصباح والمجفف على التوازي $\frac{1}{\mathrm{R}_\mathrm{p}} = \frac{1}{144} + \frac{1}{16.0}$ فـ $\mathrm{R}_\mathrm{p} = 14.4\ \Omega$، والمقاومة الكلية $0.60 + 14.4 = 15.0\ \Omega$، والتيار الكلي $\mathrm{I} = \frac{120}{15.0} = 8.00\ \text{A}$، والهبوط في الجهد عبر الأسلاك $(8.00\ \text{A})(0.60\ \Omega) = 4.8\ \text{V}$، فجهد المصباح $\mathrm{V} = (8.00\ \text{A})(14.4\ \Omega) = 115\ \text{V}$.', '["أهمل مقاومة الأسلاك فعدّ جهد المصباح مساويًا لجهد المصدر.","عامل المصباح والمجفف كأنهما موصولان على التوالي ($120 \\times \\frac{144}{160.6}$)، وهما على التوازي.","هذا الهبوط في الجهد عبر مقاومة الأسلاك لا عبر المصباح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-27T21:51:39.418Z"}'::jsonb),
('mcq', 5, 0, 'ضعف الإضاءة سببه الهبوط في الجهد عبر مقاومة الأسلاك ($\mathrm{V} = \mathrm{I}\mathrm{R}$)؛ فالأسلاك الأسمك مقاومتها أصغر، فيقل الهبوط في الجهد عبرها عند مرور التيار الكبير ويبقى جهد المصابيح قريبًا من جهد المصدر.', '["","الأسلاك الأطول مقاومتها أكبر فيزداد الهبوط في الجهد عبرها.","التيار الأكبر يزيد الهبوط في الجهد عبر مقاومة الأسلاك فيزيد ضعف الإضاءة.","التوصيل على التوالي يجعل المصابيح تتقاسم الجهد مع الجهاز فيزيد ضعفها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.418Z"}'::jsonb),
('mcq', 6, 2, 'المكيّف يحتاج إلى تيار كبير ($\frac{1440}{120} = 12\ \text{A}$ عند 120 V)، فيزداد التيار الكلي المار في مقاومة أسلاك التمديدات كثيرًا، ويزداد الهبوط في الجهد عبرها، فيقل الجهد الواصل إلى المصابيح أكثر من غيره.', '["تيار الشاحن صغير جدًّا فلا يكاد يغيّر الهبوط في الجهد عبر الأسلاك.","تيار المصباح الصغير صغير فلا يكاد يؤثر.","","تيار الساعة صغير جدًّا فلا يكاد يؤثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-27T21:51:39.418Z"}'::jsonb),
('mcq', 7, 3, 'الهبوط في الجهد عبر مقاومة السلكين $\mathrm{V} = \mathrm{I}\mathrm{R} = (15\ \text{A})(0.40\ \Omega) = 6.0\ \text{V}$، فالجهد الواصل إلى الأجهزة $120 - 6.0 = 114\ \text{V}$.', '["هذا الهبوط في الجهد عبر السلكين لا الجهد الواصل إلى الأجهزة.","أهمل الهبوط في الجهد عبر مقاومة السلكين.","جمع الهبوط في الجهد إلى جهد المصدر بدل طرحه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-27T21:51:39.419Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لو كانت المصابيح والمكيّف موصولة مباشرة بالمصدر على التوازي لما تغيّر تيار المصابيح؛ لأن فرق الجهد بين طرفي كل منها يبقى مساويًا لجهد المصدر. لكن أسلاك التمديدات المنزلية لها مقاومة صغيرة موصولة على التوالي مع مجموعة الأجهزة الموصولة على التوازي، فتكون الدائرة المنزلية دائرة مركّبة. عند تشغيل المكيّف تقل المقاومة المكافئة لجزء التوازي ويزداد التيار الكلي كثيرًا، فيزداد الهبوط في الجهد عبر مقاومة الأسلاك ($\mathrm{V} = \mathrm{I}\mathrm{R}$)، فيقل فرق الجهد الواصل إلى المصابيح، فيقل التيار المار فيها والقدرة المستنفدة، فيخفت ضوؤها.', '["في التوازي المثالي لا يتغير جهد المصباح","مقاومة الأسلاك على التوالي مع الأجهزة: دائرة مركّبة","زيادة التيار الكلي عند تشغيل المكيّف","زيادة الهبوط في الجهد عبر الأسلاك ونقص جهد المصابيح"]'::jsonb, '[]'::jsonb, '[{"element":"حالة التوازي المثالي","marks":1},{"element":"مقاومة الأسلاك على التوالي (دائرة مركّبة)","marks":1},{"element":"زيادة التيار الكلي","marks":1},{"element":"نقص جهد المصابيح وخفوت الضوء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التفسير كامل ومتسلسل"},{"level":"2–3 درجات","description":"ذكر مقاومة الأسلاك وزيادة التيار مع نقص في الربط"},{"level":"1 درجة","description":"ذكر أن المكيّف يحتاج إلى تيار كبير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن تيار المصدر ثابت فيتقاسمه المكيّف والمصابيح","القول إن جهد المصدر نفسه ينخفض","إغفال أن مقاومة الأسلاك على التوالي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-27T21:51:39.419Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $\mathrm{R} = 0.60 + 144 = 144.6\ \Omega$، $\mathrm{I} = \frac{120}{144.6} = 0.830\ \text{A}$، جهد المصباح $(0.830)(144) = 119.5\ \text{V}$، $\mathrm{P} = \frac{\mathrm{V}^2}{\mathrm{R}} = \frac{(119.5)^2}{144} = 99.2\ \text{W}$. (b) $\mathrm{R}_\mathrm{p} = \frac{(144)(16.0)}{144 + 16.0} = 14.4\ \Omega$، $\mathrm{R} = 0.60 + 14.4 = 15.0\ \Omega$، $\mathrm{I} = \frac{120}{15.0} = 8.00\ \text{A}$، جهد المصباح $(8.00)(14.4) = 115\ \text{V}$، $\mathrm{P} = \frac{(115.2)^2}{144} = 92.2\ \text{W}$. (c) زاد التيار الكلي من 0.830 A إلى 8.00 A، فزاد الهبوط في الجهد عبر مقاومة الأسلاك من نحو 0.50 V إلى 4.8 V، فنقص جهد المصباح من 119.5 V إلى 115 V ونقصت قدرته من 99.2 W إلى 92.2 W؛ فضعف ضوؤه.', '["(a) 0.830 A و119.5 V و99.2 W","$\\mathrm{R}_\\mathrm{p} = 14.4\\ \\Omega$ و$\\mathrm{R} = 15.0\\ \\Omega$","(b) 8.00 A و115 V و92.2 W","(c) زيادة الهبوط عبر الأسلاك من 0.50 V إلى 4.8 V"]'::jsonb, '["$\\mathrm{I}_1 = \\frac{120}{0.60 + 144} = 0.830\\ \\text{A}$","$\\mathrm{V}_1 = \\mathrm{I}_1(144) = 119.5\\ \\text{V}$، $\\mathrm{P}_1 = 99.2\\ \\text{W}$","$\\mathrm{R}_\\mathrm{p} = 14.4\\ \\Omega$، $\\mathrm{I}_2 = \\frac{120}{15.0} = 8.00\\ \\text{A}$","$\\mathrm{V}_2 = (8.00)(14.4) = 115\\ \\text{V}$، $\\mathrm{P}_2 = 92.2\\ \\text{W}$"]'::jsonb, '[{"element":"قيم الحالة (a)","marks":2},{"element":"المقاومة المكافئة في (b)","marks":1},{"element":"قيم الحالة (b)","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات والتفسير صحيحة"},{"level":"3–4 درجات","description":"إحدى الحالتين صحيحة كاملًا والأخرى ناقصة"},{"level":"1–2 درجة","description":"حساب التيار الكلي في حالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال مقاومة الأسلاك فيبقى جهد المصباح 120 V","جمع مقاومة المجفف مع المصباح على التوالي","استعمال $\\mathrm{P} = \\mathrm{I}^2\\mathrm{R}$ بالتيار الكلي بدل تيار المصباح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-27T21:51:39.419Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) السلكان على التوالي مع المصباح: $\mathrm{R} = 0.30 + 200 + 0.30 = 200.6\ \Omega$. (b) $\mathrm{I} = \frac{120\ \text{V}}{200.6\ \Omega} = 0.598\ \text{A}$. (c) $\mathrm{P} = \mathrm{I}^2\mathrm{R} = (0.598)^2(200) = 71.6\ \text{W}$. (d) يقل سطوع المصباح: المدفأة مقاومتها صغيرة فتشغيلها يقلل المقاومة المكافئة لجزء التوازي ويزيد التيار الكلي كثيرًا، فيزداد الهبوط في الجهد عبر سلكي التوصيل (الموصولين على التوالي مع جزء التوازي)، فيقل الجهد بين طرفي المصباح وتقل قدرته.', '["$\\mathrm{R} = 200.6\\ \\Omega$","$\\mathrm{I} = 0.598\\ \\text{A}$","$\\mathrm{P} = 71.6\\ \\text{W}$","(d) يقل السطوع","تعليل (d) بزيادة الهبوط عبر السلكين"]'::jsonb, '["$\\mathrm{R} = 0.30 + 200 + 0.30 = 200.6\\ \\Omega$","$\\mathrm{I} = \\frac{\\mathrm{V}}{\\mathrm{R}} = 0.598\\ \\text{A}$","$\\mathrm{P} = \\mathrm{I}^2\\mathrm{R} = 71.6\\ \\text{W}$"]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"التنبؤ في (d)","marks":1},{"element":"التعليل في (d)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات والتنبؤ والتعليل صحيحة"},{"level":"3–4 درجات","description":"الحسابات صحيحة مع تعليل ناقص"},{"level":"1–2 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب مقاومة سلك واحد فقط","عدّ السلكين على التوازي مع المصباح","التنبؤ بأن السطوع لا يتغير لأن الأجهزة على التوازي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-27T21:51:39.419Z"}'::jsonb)
